class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)
        def occ(pat):
            if not pat:
                return []
            m = len(pat)
            fail = [0] * m
            j = 0
            for i in range(1, m):
                while j and pat[i] != pat[j]:
                    j = fail[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                fail[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != pat[j]:
                    j = fail[j - 1]
                if ch == pat[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = fail[j - 1]
            return out
        NEG, INF = -1, n + 1
        latestA = [NEG] * (n + 1)
        if not a:
            latestA = list(range(n + 1))
        else:
            for st in occ(a):
                latestA[st + len(a)] = max(latestA[st + len(a)], st)
        for i in range(1, n + 1):
            latestA[i] = max(latestA[i], latestA[i - 1])
        earlC = [INF] * (n + 1)
        if not c:
            earlC = list(range(n + 1))
        else:
            for st in occ(c):
                earlC[st] = min(earlC[st], st + len(c))
        for i in range(n - 1, -1, -1):
            earlC[i] = min(earlC[i], earlC[i + 1])
        ans = INF
        spans = [(x, x) for x in range(n + 1)] if not b else [(st, st + len(b)) for st in occ(b)]
        for x, y in spans:
            if latestA[x] >= 0 and earlC[y] <= n:
                ans = min(ans, earlC[y] - latestA[x])
        return ans if ans <= n else -1

