class Solution {
public:
    int shortestMatchingSubstring(string s, string p) {
        int s1 = p.find('*'), s2 = p.find('*', s1 + 1);
        string a = p.substr(0, s1), b = p.substr(s1 + 1, s2 - s1 - 1), c = p.substr(s2 + 1);
        int n = s.size();
        auto kmp = [&](const string& pat) {
            vector<int> out; int m = pat.size();
            if (!m) return out;
            vector<int> f(m, 0);
            for (int i = 1, j = 0; i < m; i++) {
                while (j && pat[i] != pat[j]) j = f[j - 1];
                if (pat[i] == pat[j]) j++;
                f[i] = j;
            }
            for (int i = 0, j = 0; i < n; i++) {
                while (j && s[i] != pat[j]) j = f[j - 1];
                if (s[i] == pat[j]) j++;
                if (j == m) { out.push_back(i - m + 1); j = f[j - 1]; }
            }
            return out;
        };
        const long long NEG = -1, INF = LLONG_MAX / 2;
        vector<long long> lA(n + 1, NEG), eC(n + 1, INF);
        if (a.empty()) for (int i = 0; i <= n; i++) lA[i] = i;
        else for (int st : kmp(a)) lA[st + a.size()] = max(lA[st + a.size()], (long long)st);
        for (int i = 1; i <= n; i++) lA[i] = max(lA[i], lA[i - 1]);
        if (c.empty()) for (int i = 0; i <= n; i++) eC[i] = i;
        else for (int st : kmp(c)) eC[st] = min(eC[st], (long long)(st + (int)c.size()));
        for (int i = n - 1; i >= 0; i--) eC[i] = min(eC[i], eC[i + 1]);
        long long ans = INF;
        if (b.empty()) {
            for (int x = 0; x <= n; x++)
                if (lA[x] >= 0 && eC[x] <= n) ans = min(ans, eC[x] - lA[x]);
        } else {
            for (int st : kmp(b)) {
                int y = st + b.size();
                if (lA[st] >= 0 && eC[y] <= n) ans = min(ans, eC[y] - lA[st]);
            }
        }
        return ans < INF ? (int)ans : -1;
    }
};

