class Solution {
    private String s;
    private int[] fail(String p) {
        int m = p.length(); int[] f = new int[m];
        for (int i = 1, j = 0; i < m; i++) {
            while (j > 0 && p.charAt(i) != p.charAt(j)) j = f[j - 1];
            if (p.charAt(i) == p.charAt(j)) j++;
            f[i] = j;
        }
        return f;
    }
    private List<Integer> occ(String p) {
        List<Integer> out = new ArrayList<>(); int m = p.length();
        if (m == 0) return out;
        int[] f = fail(p);
        for (int i = 0, j = 0; i < s.length(); i++) {
            while (j > 0 && s.charAt(i) != p.charAt(j)) j = f[j - 1];
            if (s.charAt(i) == p.charAt(j)) j++;
            if (j == m) { out.add(i - m + 1); j = f[j - 1]; }
        }
        return out;
    }
    public int shortestMatchingSubstring(String s, String p) {
        this.s = s; int n = s.length();
        int s1 = p.indexOf('*'), s2 = p.indexOf('*', s1 + 1);
        String a = p.substring(0, s1), b = p.substring(s1 + 1, s2), c = p.substring(s2 + 1);
        long NEG = -1, INF = Long.MAX_VALUE / 2;
        long[] lA = new long[n + 1], eC = new long[n + 1];
        Arrays.fill(lA, NEG); Arrays.fill(eC, INF);
        if (a.isEmpty()) for (int i = 0; i <= n; i++) lA[i] = i;
        else for (int st : occ(a)) lA[st + a.length()] = Math.max(lA[st + a.length()], st);
        for (int i = 1; i <= n; i++) lA[i] = Math.max(lA[i], lA[i - 1]);
        if (c.isEmpty()) for (int i = 0; i <= n; i++) eC[i] = i;
        else for (int st : occ(c)) eC[st] = Math.min(eC[st], st + (long) c.length());
        for (int i = n - 1; i >= 0; i--) eC[i] = Math.min(eC[i], eC[i + 1]);
        long ans = INF;
        if (b.isEmpty()) {
            for (int x = 0; x <= n; x++)
                if (lA[x] >= 0 && eC[x] <= n) ans = Math.min(ans, eC[x] - lA[x]);
        } else {
            for (int st : occ(b)) {
                int y = st + b.length();
                if (lA[st] >= 0 && eC[y] <= n) ans = Math.min(ans, eC[y] - lA[st]);
            }
        }
        return ans < INF ? (int) ans : -1;
    }
}

