var shortestMatchingSubstring = function(s, p) {
    const [a, b, c] = p.split('*');
    const n = s.length;
    const occ = pat => {
        if (!pat) return [];
        const m = pat.length, f = new Array(m).fill(0), out = [];
        for (let i = 1, j = 0; i < m; i++) {
            while (j && pat[i] !== pat[j]) j = f[j - 1];
            if (pat[i] === pat[j]) j++;
            f[i] = j;
        }
        for (let i = 0, j = 0; i < n; i++) {
            while (j && s[i] !== pat[j]) j = f[j - 1];
            if (s[i] === pat[j]) j++;
            if (j === m) { out.push(i - m + 1); j = f[j - 1]; }
        }
        return out;
    };
    const NEG = -1, INF = n + 1;
    let lA = new Array(n + 1).fill(NEG), eC = new Array(n + 1).fill(INF);
    if (!a) lA = [...Array(n + 1).keys()];
    else for (const st of occ(a)) lA[st + a.length] = Math.max(lA[st + a.length], st);
    for (let i = 1; i <= n; i++) lA[i] = Math.max(lA[i], lA[i - 1]);
    if (!c) eC = [...Array(n + 1).keys()];
    else for (const st of occ(c)) eC[st] = Math.min(eC[st], st + c.length);
    for (let i = n - 1; i >= 0; i--) eC[i] = Math.min(eC[i], eC[i + 1]);
    let ans = INF;
    const spans = !b ? [...Array(n + 1).keys()].map(x => [x, x])
                     : occ(b).map(st => [st, st + b.length]);
    for (const [x, y] of spans)
        if (lA[x] >= 0 && eC[y] <= n) ans = Math.min(ans, eC[y] - lA[x]);
    return ans <= n ? ans : -1;
};
